const visualStyle=document.createElement('style');visualStyle.textContent="\n/* Areia Amigos: visual do modelo aprovado para carregadores e administradores */\n.av-shell{background:#0b1727!important;color:#f3f8ff!important;border-radius:14px;overflow:hidden;min-height:calc(100vh - 190px)}\n.av-sidebar{background:linear-gradient(155deg,#0b1b31,#10243b)!important}.av-main-content{background:#0b1727!important;min-width:0}.av-topbar{background:linear-gradient(100deg,#0c1e33,#102944)!important;border-bottom:1px solid #34516e!important}.av-topbar h1{font-size:clamp(25px,3vw,36px)!important;color:#fff!important}.av-topbar p{color:#d4e4f7!important}.av-topbar small{color:#b4d2ee!important}.av-user strong,.av-user small{color:#fff!important}.av-page{padding:24px!important}.av-side-nav button{border-radius:12px!important}.av-side-nav button.active{background:#086be5!important;color:#fff!important}.av-layout.av-load-layout{grid-template-columns:minmax(0,1.65fr) minmax(310px,1fr);gap:20px}.av-load-layout>.av-panel{background:linear-gradient(135deg,#132b45,#15283e)!important;border:1px solid #486583!important;border-radius:18px!important;padding:24px!important;box-shadow:0 10px 28px #020c1a30}.av-step{display:flex;align-items:center;gap:14px;color:#fff!important;font-size:clamp(18px,2vw,23px)!important;margin:0 0 22px!important}.av-step span{display:grid;place-items:center;flex:0 0 42px;width:42px;height:42px;border-radius:50%;background:#147af4;color:#fff;font-size:22px}.av-separator{border:0;border-top:1px solid #425e79;margin:28px 0}.av-load-form .av-grid{gap:20px 18px}.av-load-form .av-field{font-size:15px;color:#f4f8ff!important;font-weight:600}.av-load-form .av-field input,.av-load-form .av-field select{height:49px!important;border-radius:9px!important;background:#0c1b2c!important;border:1px solid #56718c!important;color:#fff!important;font-size:15px!important;padding:12px 15px!important}.av-load-form input::placeholder{color:#c0d1e4!important;opacity:1}.av-load-form .av-field input:focus,.av-load-form .av-field select:focus{outline:2px solid #2c9cff}.av-load-form .av-total{display:flex;align-items:center;gap:22px;background:linear-gradient(110deg,#065b46,#086a51)!important;border:1px solid #10e5a1!important;border-radius:12px!important;margin-top:26px;padding:20px 24px!important;color:white!important}.av-total>span{font-size:36px}.av-total small{display:block;font-size:18px;color:#fff}.av-total strong{display:block;font-size:32px;line-height:1.2}.av-save-note{font-size:15px;color:#e7f1fc!important}.av-save-actions{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin-top:24px}.av-save-actions .av-main{padding:15px 25px!important;border-radius:10px!important;background:#ff9215!important;color:#101d2b!important;font-size:16px}.av-clear{padding:13px 23px;background:#273b54;color:#fff!important;border:1px solid #8295ae;border-radius:9px;cursor:pointer}.av-receipt-panel h2{color:#fff!important;font-size:23px!important}.av-receipt-panel .av-empty{border:1px dashed #7793b1;border-radius:15px;min-height:220px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;font-size:18px;color:#e5f1ff;background:#12273d}.av-receipt-panel .av-empty:first-letter{font-size:40px}.av-receipt-panel .av-actions{display:flex;flex-direction:column;gap:10px;margin-top:20px}.av-receipt-panel .av-actions button{width:100%;min-height:52px;border:1px solid #47647f;border-radius:10px;background:#162c44!important;color:#fff!important;font-size:15px;text-align:left;padding:12px 18px;cursor:pointer}.av-receipt-panel .av-actions button:disabled{opacity:.65;cursor:not-allowed}.av-receipt-panel .av-receipt{white-space:pre-wrap;color:#fff;background:#0c1d30;border:1px solid #496682;border-radius:12px;padding:18px;line-height:1.65}@media(max-width:1050px){.av-layout.av-load-layout{grid-template-columns:1fr}.av-receipt-panel .av-empty{min-height:160px}}@media(max-width:600px){.av-page{padding:12px!important}.av-load-layout>.av-panel{padding:16px!important}.av-load-form .av-grid{grid-template-columns:1fr}.av-save-actions>*{width:100%}.av-step{font-size:18px!important}.av-topbar{gap:10px}.av-user{flex-shrink:0}}\n";document.head.append(visualStyle);
